Here's a Python function to parse inspection reports from structured PDFs:

```python
import re
from dataclasses import dataclass, field
from typing import List, Optional

@dataclass
class Finding:
    section: str
    severity: str  # 'critical' | 'major' | 'minor'
    description: str
    action_required: Optional[str] = None

@dataclass  
class InspectionReport:
    report_id: str
    date: str
    inspector: str
    findings: List[Finding] = field(default_factory=list)

def parse_inspection_report(text: str) -> InspectionReport:
    """Parse raw inspection report text into structured data."""
    lines = text.strip().split('\n')

    report = InspectionReport(
        report_id=_extract(lines, r'Report ID:\s*([\w-]+)'),
        date=_extract(lines, r'Date:\s*([\d/]+)'),
        inspector=_extract(lines, r'Inspector:\s*(.+)')
    )

    # Parse non-conformance sections
    nc_pattern = re.compile(
        r'(\d+\.\d+)\s*[-–]\s*(.+?)(?=\d+\.\d+|$)', 
        re.DOTALL
    )
    for match in nc_pattern.finditer(text):
        report.findings.append(Finding(
            section=match.group(1),
            severity=_classify_severity(match.group(2)),
            description=match.group(2).strip()
        ))

    return report

def _extract(lines, pattern):
    for line in lines:
        m = re.search(pattern, line)
        if m: return m.group(1)
    return ''

def _classify_severity(text: str) -> str:
    text_lower = text.lower()
    if any(w in text_lower for w in ['immediate', 'critical', 'safety']):
        return 'critical'
    if any(w in text_lower for w in ['required', 'non-conform', 'must']):
        return 'major'
    return 'minor'
